<?php
require_once dirname(__DIR__) . '/auth.php';
require_once dirname(__DIR__) . '/app/data-slot.php';
require_once dirname(__DIR__) . '/app/beheer/editor-hulp.php';
if(!$ingelogd){header('Location: ../beheer.php');exit;}
$rechten=authRechten(['nieuws'=>'Nieuws'],[]);if(!$isMaster&&!in_array('nieuws',$rechten['toegestaneTabs']??[],true)){http_response_code(403);echo'Geen toegang tot Nieuws.';exit;}
$bestand=dirname(__DIR__).'/data/nieuws.json';$data=beheerEditorLeesJson($bestand,[]);$melding='';$type='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 if(!csrfOk()){$melding='Sessie verlopen. Ververs de pagina en probeer opnieuw.';$type='fout';}
 else{$items=[];$fout='';foreach((array)($_POST['nieuws']??[]) as $rij){if(!is_array($rij))continue;$titelNl=beheerEditorKort($rij['title_nl']??'',100);if($titelNl==='')continue;$link=trim((string)($rij['link']??''));if($link!==''&&!preg_match('#^https?://#i',$link)){$fout='Link bij “'.$titelNl.'” moet beginnen met http:// of https://.';break;}$items[]=['date'=>beheerEditorDatumIso($rij['date']??''),'title'=>['nl'=>$titelNl,'en'=>beheerEditorKort($rij['title_en']??'',100),'de'=>beheerEditorKort($rij['title_de']??'',100)],'desc'=>['nl'=>beheerEditorKort($rij['desc_nl']??'',300),'en'=>beheerEditorKort($rij['desc_en']??'',300),'de'=>beheerEditorKort($rij['desc_de']??'',300)],'link'=>$link,'linktekst'=>['nl'=>beheerEditorKort($rij['linktekst_nl']??'',40),'en'=>beheerEditorKort($rij['linktekst_en']??'',40),'de'=>beheerEditorKort($rij['linktekst_de']??'',40)]];}
 if($fout!==''){$melding=$fout;$type='fout';}else{$slot=dataSlotOpen();try{$ok=beheerEditorSchrijfJson($bestand,$items);}finally{dataSlotDicht($slot);}if($ok){$data=$items;$melding='Nieuws opgeslagen.';$type='ok';schrijfLog($logBestand,$huidigeGebruiker,'nieuws',count($items).' item(s) opgeslagen');}else{$melding='Opslaan mislukt.';$type='fout';}}}
}
$data[]=['date'=>'','title'=>['nl'=>'','en'=>'','de'=>''],'desc'=>['nl'=>'','en'=>'','de'=>''],'link'=>'','linktekst'=>['nl'=>'','en'=>'','de'=>'']];
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Nieuws beheren</title><style>body{margin:0;background:#f6f2e8;color:#26351d;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.top{background:#fff;border-bottom:1px solid #ddd8c0;padding:16px 24px}.topin,.wrap{max-width:1180px;margin:auto}.topin{display:flex;justify-content:space-between}.top a{color:#2d6260;text-decoration:none;font-weight:700}.wrap{padding:30px 24px 70px}.kaart{background:#fff;border:1px solid #ddd8c0;border-radius:14px;padding:22px;margin-bottom:18px}.talen{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.veld{margin-bottom:14px}.veld label,.taal label{display:block;font-weight:700;font-size:12px;margin:6px 0}.veld input,.taal input,.taal textarea{width:100%;box-sizing:border-box;border:1px solid #cfcab7;border-radius:8px;padding:10px;font:inherit}.taal textarea{min-height:90px}.melding{padding:12px 14px;border-radius:9px;margin-bottom:18px}.ok{background:#e8f5ee;color:#205b38}.fout{background:#fdeceb;color:#8b2e27}.btn{background:#3a7a77;color:#fff;border:0;border-radius:9px;padding:11px 18px;font-weight:700;cursor:pointer}.hint{color:#68705f}@media(max-width:800px){.talen{grid-template-columns:1fr}}</style></head><body><div class="top"><div class="topin"><a href="./">← Terug naar beheer</a><a href="../index.html#nieuws" target="_blank" rel="noopener">Bekijk nieuws ↗</a></div></div><main class="wrap"><h1>Nieuws</h1><p class="hint">Leeg de Nederlandse titel en sla op om een item te verwijderen. Onderaan staat altijd één leeg item.</p><?php if($melding!==''):?><div class="melding <?=beheerEditorEsc($type)?>"><?=beheerEditorEsc($melding)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=beheerEditorEsc($csrfToken)?>"><?php foreach($data as $i=>$item):?><section class="kaart"><h2>Nieuwsitem <?=($i+1)?></h2><div class="veld"><label>Datum (dd-mm-jjjj)</label><input name="nieuws[<?=$i?>][date]" maxlength="10" value="<?=beheerEditorEsc(beheerEditorDatumNl($item['date']??''))?>"></div><div class="talen"><?php foreach(['nl'=>'Nederlands','en'=>'Engels','de'=>'Duits'] as $t=>$label):?><div class="taal"><label><?=beheerEditorEsc($label)?> titel<?=$t==='nl'?'':' (optioneel)'?></label><input name="nieuws[<?=$i?>][title_<?=$t?>]" maxlength="100" value="<?=beheerEditorEsc($item['title'][$t]??'')?>"><label>Tekst</label><textarea name="nieuws[<?=$i?>][desc_<?=$t?>]" maxlength="300"><?=beheerEditorEsc($item['desc'][$t]??'')?></textarea><label>Linktekst</label><input name="nieuws[<?=$i?>][linktekst_<?=$t?>]" maxlength="40" value="<?=beheerEditorEsc($item['linktekst'][$t]??'')?>"></div><?php endforeach;?></div><div class="veld"><label>Link (optioneel)</label><input name="nieuws[<?=$i?>][link]" value="<?=beheerEditorEsc($item['link']??'')?>" placeholder="https://..."></div></section><?php endforeach;?><button class="btn" type="submit">Nieuws opslaan</button></form></main></body></html>
